<?php require 'includes.php'; $s=settings(); $db=db_load(); $success=''; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $db['inquiries'][]=['id'=>make_id(),'type'=>'Appointment Request','name'=>trim(post('name')),'mobile'=>trim(post('mobile')),'email'=>trim(post('email')),'message'=>trim(post('message')),'appointment_date'=>post('date'),'appointment_time'=>post('time'),'dob'=>post('dob'),'age'=>(int)post('age'),'city'=>trim(post('city')),'state'=>trim(post('state')),'country'=>trim(post('country')),'address'=>trim(post('address')),'gender'=>post('gender'),'blood_group'=>post('blood_group'),'created_at'=>now_iso(),'status'=>'New']; db_save($db); $success='Appointment request submitted successfully. Our clinic will contact you to confirm the appointment.'; } $page_title='Book Appointment | '.$s['clinic_name']; require 'header.php'; ?><section class="page-head"><div class="container"><h1>Book an Appointment</h1><p>Enter patient details and choose your preferred appointment slot.</p></div></section><section class="section"><div class="container"><div class="form-card"><?php if($success): ?><div class="notice"><?=e($success)?></div><?php endif; ?><form method="post"><div class="form-grid"><div class="field"><label>Patient Name *</label><input required name="name"></div><div class="field"><label>DOB *</label><input required type="date" id="dob" name="dob" onchange="calcAge()"></div><div class="field"><label>Age (Auto)</label><input id="age" name="age" readonly></div><div class="field"><label>City</label><input name="city"></div><div class="field"><label>State</label><input name="state"></div><div class="field"><label>Country</label><input name="country" value="India"></div><div class="field full"><label>Address</label><textarea name="address" rows="3"></textarea></div><div class="field"><label>Mobile Number *</label><input required name="mobile" inputmode="numeric" pattern="[0-9+ ]{8,15}"></div><div class="field"><label>Gender</label><div class="check-row"><label><input type="radio" name="gender" value="Male" checked> Male</label><label><input type="radio" name="gender" value="Female"> Female</label><label><input type="radio" name="gender" value="Other"> Other</label></div></div><div class="field"><label>Blood Group</label><select name="blood_group"><option value="">Select</option><?php foreach(['A+','A-','B+','B-','AB+','AB-','O+','O-'] as $g): ?><option><?=e($g)?></option><?php endforeach; ?></select></div><div class="field"><label>Email</label><input type="email" name="email"></div><div class="field full"><label>Message / Reason for Visit</label><textarea name="message" rows="3"></textarea></div><div class="field"><label>Appointment Date *</label><input required type="date" name="date"></div><div class="field"><label>Appointment Time *</label><input required type="time" name="time"></div><div class="field full"><button class="btn" type="submit">Confirm Appointment</button></div></div></form></div></div></section><?php require 'footer.php'; ?>
